// Separa la marca [TRANSFERIR] de la respuesta al cliente (criterio C-11).
const entradas = $('Normalizar entrada').all();
const cfg = $('Config del negocio').first().json;
const cierre = String(cfg.mensajeCierre ?? '').trim()
  || 'Gracias por escribirnos. Si necesita algo mas, escribame por aca.';
const falla = String(cfg.mensajeErrorTemporal ?? '').trim()
  || 'Disculpe, tuve un problema tecnico momentaneo. Me repite lo ultimo?';

// `isExecuted` es de toda la ejecucion, no del item: se lee una sola vez, y
// protegido, porque si la referencia fallara la verificacion tiene que
// seguir abierta por las otras dos vias.
let herramientaAgendarCorrio = false;
try { herramientaAgendarCorrio = $('agendar_cita').isExecuted === true; }
catch (e) { herramientaAgendarCorrio = false; }

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  // Emparejamiento por indice: nunca .first(), que le pondria el telefono del
  // primer cliente a la respuesta del segundo cuando llegan dos a la vez.
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const dato = items[i].json;

  // Gemini devuelve 500/503 en picos y entonces no llega `output`. Hay que
  // distinguirlo de una respuesta vacia: despedirse cuando en realidad se cayo
  // el modelo deja al cliente creyendo que la conversacion termino.
  const fallo = dato.error !== undefined || dato.output === undefined;
  const texto = String(dato.output ?? '').trim();
  const transferir = texto.includes('[TRANSFERIR]');
  // UBICACION (Analisis/34 §2). La marca [ENVIAR_UBICACION] la escribe el
  // modelo SOLO cuando el cliente pidio expresamente el pin. Se quita del
  // texto siempre; el `location` nativo se manda solo si el comercio cargo
  // las coordenadas: sin ellas el texto ya lleva la direccion y el enlace, y
  // no hay nada mas que mandar. Cuesta un mensaje mas, solo en ese caso.
  const pideUbicacion = /\[ENVIAR_UBICACION\]/i.test(texto);
  let respuesta = texto.split('[TRANSFERIR]').join('')
    .replace(/\[ENVIAR_UBICACION\]/gi, '')
    // Cualquier otra marca en corchetes que el modelo invente, para que el
    // cliente nunca la vea (mismo criterio que el Demo B).
    .replace(/\[[A-ZÁÉÍÓÚÑ_ ]{3,30}\]/g, '')
    .trim();

  // El nodo de WhatsApp rechaza un cuerpo vacio con 400 Bad request. Pero una
  // respuesta vacia NO significa que la conversacion termino: el 2026-08-30 el
  // modelo devolvio cadena vacia en plena reserva y el cierre cortes hizo creer
  // al cliente que estaba todo listo, cuando no se habia agendado nada.
  // La despedida se detecta en lo que ESCRIBIO EL CLIENTE, no se deduce de que
  // el modelo no haya contestado. Ante la duda, un error recuperable -- que
  // invita a repetir -- es mucho mejor que un cierre, que corta.
  const DESPEDIDA = /^\s*(muchas\s+)?(gracias|grax|chau|chao|adios|adiós|listo|ok|oka|dale|perfecto|hasta\s+luego|nos\s+vemos|buenas\s+noches)\b[\s.!¡👍🙏😊]*$/i;
  const seDespide = DESPEDIDA.test(String(items[i].json.userInput ?? ''));

  const vacia = respuesta === '';
  if (fallo) respuesta = falla;
  else if (vacia) respuesta = seDespide ? cierre : falla;

  // NEGRITA DE WHATSAPP, POR CONSTRUCCION (2026-09-17). El prompt pide UN
  // asterisco y el modelo sigue escribiendo **texto**, que WhatsApp muestra
  // con los asteriscos a la vista. Se corrige aca, determinista, en vez de
  // pedirselo otra vez al modelo: ***x*** -> *_x_* (negrita cursiva) y
  // **x** -> *x*. Un asterisco solo (vinetas, «2 * 3») no se toca. La MISMA
  // linea vive en `Procesar reintento` y en `Mensaje a enviar`, que es la
  // salida unica al cliente; una prueba exige que las tres sean identicas.
  const NEGRITA_MD = (t) => String(t).replace(/\*\*\*([^*\n]+?)\*\*\*/g, '*_$1_*').replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
  respuesta = NEGRITA_MD(respuesta);

  // --- PROHIBICION 3 CON DINERO REAL (seña por QR, bloque 2) ------------------
  // Con la seña activa el asistente maneja un cobro REAL: el QR es el del
  // comercio y el dinero va a su cuenta. CLAUDE.md, prohibicion 3: NUNCA
  // «pago acreditado», «pago verificado» ni «recibimos tu pago». El prompt lo
  // dice, pero un prompt no es una barrera (ya se rompio al cambiar de
  // modelo): si el modelo lo afirma igual, la ORACION se reemplaza por lo
  // unico cierto --el comprobante lo revisa el negocio, y el negocio confirma
  // el pago-- y queda anotado en `avisos`. Mismo regex que la red del cobro
  // simulado del Demo B; se juzga sin marcas de formato.
  const avisos = [];
  const AFIRMA_COBRO = /((pago|cobro|transferencia|dep[oó]sito|abono)\s+(\S+\s+){0,3}(verificad|confirmad|recibid|acreditad|procesad|aprobad|realizad|efectuad|exitos)|ya\s+(recibimos|se\s+acredit|te\s+cobr|se\s+cobr)|(pago|cobro)\s+(\S+\s+){0,2}(real|de\s+verdad))/i;
  if (cfg.senaActiva === 'si' && AFIRMA_COBRO.test(respuesta.replace(/[*_~]/g, ''))) {
    const quienRevisa = String(cfg.nombreNegocio || '').trim() || 'el negocio';
    const CORRECCION = `El comprobante lo revisa ${quienRevisa} y ellos confirman el pago.`;
    respuesta = respuesta.split('\n').map((linea) => linea.split(/(?<=[.!?…])\s+/)
      .map((o) => (AFIRMA_COBRO.test(o.replace(/[*_~]/g, '')) ? CORRECCION : o)).join(' ')).join('\n').trim();
    avisos.push('correccion_cobro');
  }

  // Marca si la respuesta AFIRMA que la cita quedo agendada. Se decide aca y
  // no en una expresion del nodo IF para poder probarlo: la trampa es que
  // "ya tiene reservada su cita" no es una confirmacion nueva sino un aviso
  // de que el horario esta ocupado, y disparar la compuerta ahi romperia una
  // conversacion correcta. Probado contra las frases reales del agente.
  // Solo cuentan las formas de HECHO CONSUMADO. "agendamos" y "reservamos"
  // salieron de la lista: en espanol son a la vez presente y pasado, y el
  // agente las usa para OFRECER ("con gusto agendamos tu cita"). El
  // 2026-08-29 esa ambiguedad disparo la compuerta en plena conversacion y le
  // dijo al cliente que no se pudo registrar una cita que nadie habia pedido.
  // EL DETECTOR NO PUEDE DEPENDER DE UNA REDACCION. La version anterior exigia
// un verbo antes del participio --«quedó confirmada»-- y el 6 de septiembre el
// modelo escribio «✅ Cita confirmada para corte con José», sin verbo. No
// coincidio, la compuerta de verificacion NI SIQUIERA CORRIO, y el cliente
// recibio una confirmacion de una cita que no existia: la credencial de Google
// habia perdido el acceso y `agendar_cita` fallo.
//
// Lo que lo desencadeno fue cambiar de modelo: Flash-Lite redacta distinto, y
// el detector estaba afinado a las frases del modelo anterior. Un detector
// atado a como escribe un modelo se rompe cada vez que se cambia de modelo.
// Por eso ahora tambien reconoce la forma sin verbo, y hay una NEGACION
// explicita para que «No pude confirmar tu cita» no dispare la compuerta.
//
// 2026-09-17, ejecucion #2936: «He reprogramado tu cita» no coincidia con
// nada de esto y una cita quedo encima de otra sin verificar. Se agregan
// reprogram-, reagend-, mov-, «te anote/anotamos» y «cambie tu cita». PERO
// ESTE DETECTOR YA NO ES LA PRIMERA DEFENSA: la verificacion se dispara por
// lo que el modelo HIZO (ver mas abajo, `ejecutoAgendar`); el regex queda
// como red adicional, y se juzga sobre el texto SIN marcas de formato.
const CONFIRMA = /(ha sido|han sido|queda|quedó|quedo|fue|está|esta|ya está|ya esta)\s+(agendad|reservad|registrad|confirmad|reprogramad|reagendad|movid|cambiad|anotad)|\b(he|hemos)\s+(agendado|reservado|registrado|confirmado|reprogramado|reagendado|movido|anotado)\b|(agendé|reservé|registré|reprogramé|reagendé|moví)(?![a-záéíóúñ])|\b(te|le|les|los|las)\s+anot(é|amos)(?![a-záéíóúñ])|\b(cambié|cambiamos|moví|movimos)\s+(tu|su|la)\s+cita\b|\b(cita|reserva|turno)\b[^.!?]{0,40}?\b(agendad|reservad|registrad|confirmad|reprogramad|reagendad|movid|cambiad)[oa]s?\b/i;
const NIEGA = /\bno\s+(pude|se pudo|pudimos|quedó|quedo|está|esta)\b/i;
  const YA_EXISTE = /\bya\s+(tiene|tienes|cuenta con|hay)/i;
  // Sin marcas de formato: «quedó *agendada*» cuenta igual que «quedó agendada».
  const plano = respuesta.replace(/[*_~]/g, '');
  const afirmaAgendo = CONFIRMA.test(plano) && !YA_EXISTE.test(plano) && !NIEGA.test(plano);

  // Coordenadas del pin, de la configuracion (consola o respaldo). Viajan
  // como texto porque Config base es un Set de textos; aca se vuelven numero
  // y se comprueba el rango. Con una sola, o con basura, no se manda nada.
  const coordenada = (v, max) => {
    const t = String(v ?? '').trim();
    const n = Number(t);
    return t !== '' && Number.isFinite(n) && Math.abs(n) <= max ? n : null;
  };
  const lat = coordenada(cfg.ubicacionLat, 90);
  const lng = coordenada(cfg.ubicacionLng, 180);
  // Si el modelo escribio SOLO la marca, la respuesta queda vacia y sale el
  // texto de error: ahi tampoco va el pin. Nunca un pin sin la direccion en el texto.
  const enviarUbicacion = pideUbicacion && !vacia && lat !== null && lng !== null;

  // --- LO QUE EL MODELO HIZO, no lo que dijo (2026-09-17, ejecucion #2936) --
  // La paciente insistio («¿A las 10 no tienes?»), consultar_disponibilidad
  // le devolvio una cita de 10:00 a 11:00 y el modelo llamo a agendar_cita a
  // las 10:00 igual, con la regla de intervalos recien publicada en el
  // prompt. Y escribio «He reprogramado tu cita», que CONFIRMA no cubria: la
  // compuerta no corrio y la cita quedo encima de otra. Dos lecciones: el
  // prompt no es una barrera, y el candado no puede depender de un verbo.
  // Desde aca la verificacion se dispara si la herramienta SE EJECUTO, por
  // dos vias que no dependen de la redaccion:
  //   1. `intermediateSteps` de la salida del agente (opcion «Return
  //      Intermediate Steps» del nodo): cada herramienta invocada, con sus
  //      argumentos y lo que devolvio. Es por item, y trae el `id` del
  //      evento que agendar_cita creo; `Comprobar reserva` lo usa para
  //      anclar el candado a ESA cita y no solo a «lo creado hace 5 min».
  //   2. `$('agendar_cita').isExecuted`: n8n lo responde con la presencia
  //      del nodo en los datos de la ejecucion, y una herramienta invocada
  //      queda ahi (en la #2936 `agendar_cita` figura con su salida bajo
  //      `ai_tool`; en la #2933, que no agendo, no figura). Lo que NO sirve
  //      es `$('agendar_cita').all()`: lee la salida `main`, y una
  //      herramienta solo tiene `ai_tool`.
  // El regex queda como tercera red. Cualquiera de las tres abre la
  // verificacion (`verificarReserva`), que es lo que lee `¿Afirma que agendó?`.
  const pasos = Array.isArray(dato.intermediateSteps) ? dato.intermediateSteps : [];
  const herramientas = pasos.map((p) => String((p && p.action && p.action.tool) || '')).filter(Boolean);
  const eventosCreados = [];
  for (const p of pasos) {
    if (!p || !p.action || p.action.tool !== 'agendar_cita') continue;
    // La observacion es lo que devolvio la herramienta: el evento creado,
    // como texto JSON (asi lo entrega n8n) o ya como objeto.
    let obs = p.observation;
    if (typeof obs === 'string') { try { obs = JSON.parse(obs); } catch (e) { obs = null; } }
    const lista = Array.isArray(obs) ? obs : (obs && typeof obs === 'object' ? [obs] : []);
    for (const ev of lista) {
      if (!ev || !ev.id) continue;
      eventosCreados.push({
        id: String(ev.id),
        calendario: String((ev.organizer && ev.organizer.email) || ''),
        inicio: String((ev.start && ev.start.dateTime) || ''),
        fin: String((ev.end && ev.end.dateTime) || ''),
        titulo: String(ev.summary || ''),
      });
    }
  }
  const ejecutoAgendar = herramientas.includes('agendar_cita') || herramientaAgendarCorrio;
  const verificarReserva = ejecutoAgendar || afirmaAgendo;

  out.push({ json: {
    respuesta,
    transferir,
    motivoTransferencia: transferir ? 'tres rechazos de horario consecutivos' : '',
    afirmaAgendo,
    ejecutoAgendar,
    verificarReserva,
    herramientas,
    eventosCreados,
    respuestaVacia: vacia,
    seDespide,
    falloModelo: fallo,
    from: ent.from,
    nombrePerfil: ent.nombrePerfil,
    enviarUbicacion,
    // Lo que el envio del pin necesita, arrastrado en el item (como en el
    // Demo B): `Enviar ubicacion` lo lee de `Mensaje a enviar`, porque el
    // $json que le llega de `Responder al cliente` es la respuesta de Meta.
    phoneNumberId: cfg.phoneNumberId,
    waGraphVersion: cfg.waGraphVersion || 'v26.0',
    ubicacionLat: lat,
    ubicacionLng: lng,
    direccion: String(cfg.direccion ?? ''),
    nombreNegocio: String(cfg.nombreNegocio ?? ''),
    // SEÑA (bloque 2): lo que `Preparar seña` y el QR necesitan, arrastrado
    // en el item; la compuerta `¿Enviar QR de la seña?` lee `senaActiva` de
    // aca, despues del candado. `calendarioDelEvento` es el del evento que
    // agendar_cita devolvio; `Preparar seña` lo confirma contra el calendario.
    avisos,
    senaActiva: cfg.senaActiva === 'si' ? 'si' : '',
    senaImporte: String(cfg.senaImporte ?? ''),
    senaMoneda: String(cfg.senaMoneda ?? 'Bs'),
    senaMinutosRetencion: String(cfg.senaMinutosRetencion ?? '30'),
    senaQrUrl: String(cfg.senaQrUrl ?? ''),
    senaNombreCuenta: String(cfg.senaNombreCuenta ?? ''),
    senaBanco: String(cfg.senaBanco ?? ''),
    direccionMaps: String(cfg.direccionMaps ?? ''),
    funcionarios: String(cfg.funcionarios ?? '[]'),
    calendarioDelEvento: eventosCreados.length ? eventosCreados[0].calendario : '',
  }});
}
return out;

// COMPUERTA DE VERIFICACION DE RESERVA — y CANDADO CONTRA LA DOBLE RESERVA.
//
// Historia, porque el diseño cambio por evidencia y no por gusto: la primera
// version reemplazaba la respuesta por una disculpa cuando no podia verificar
// la cita. Fallo cuatro veces por falso negativo, y CADA vez el daño real no lo
// hizo la compuerta sino la reaccion en cadena: el cliente leia la disculpa,
// insistia, y el agente volvia a llamar a agendar_cita. Asi aparecieron tres
// pedicures, tres ortodoncias y dos pares de citas duplicadas.
//
// Por eso, cuando NO puede verificar, no toca el mensaje: avisa a recepcion y
// sigue. Falla ABIERTA. Un falso negativo solo genera un aviso de mas.
//
// ---------------------------------------------------------------------------
// EL CANDADO (2026-09-06). Falla CERRADA, al reves que lo de arriba, y por una
// razon distinta.
//
// QUE PASO. En una prueba real el agente propuso las 9:00 sin consultar el
// calendario ni una vez -- comprobado ejecucion por ejecucion, de la #944 a la
// #968 -- y reservo encima de una cita que ya existia. Un funcionario quedo con
// dos citas de 9 a 10. Se corrigio el prompt, pero un prompt es una instruccion
// y ya se rompio una vez al cambiar de modelo: dos clientes presentandose a la
// misma hora no puede depender de que el modelo obedezca.
//
// COMO FUNCIONA, sin una sola consulta extra. `Verificar en el calendario` ya
// trae TODOS los eventos de TODOS los calendarios, y cada evento viene con
// `organizer.email`, que es el identificador del calendario donde vive. Con eso
// alcanza: si la cita recien creada se superpone con otra del MISMO calendario,
// hay doble reserva. Distinto calendario no es conflicto -- Maria y Jose pueden
// atender los dos a las 10:00, que es justamente para lo que existen las
// agendas por persona.
//
// QUIEN CEDE. Se borra la MAS NUEVA. Asi dos conversaciones simultaneas no se
// borran mutuamente: la que llego primero se queda con el horario.
//
// LIMITE CONOCIDO: la consulta trae hasta 50 eventos por calendario en 90 dias.
// Un negocio con mas citas que eso podria dejar una superposicion sin ver. Hay
// que subir el limite o acotar la ventana antes del primer cliente grande.
const previos = $('Procesar respuesta').all();
const VENTANA_MS = 5 * 60 * 1000;
const ahora = Date.now();

const todos = $input.all().map(i => i.json).filter(e => e && e.id);

const item = previos[0].json;

// LOS EVENTOS QUE agendar_cita DEVOLVIO (2026-09-17, ejecucion #2936). Vienen
// de `Procesar respuesta`, que los saca de los pasos intermedios del agente.
// Cuentan como «recien creados» por su id, aunque la marca `created` cayera
// fuera de la ventana de cinco minutos (reloj corrido, ejecucion lenta): el
// ancla es la cita que la herramienta dijo haber creado, y la ventana queda
// como respaldo para cuando esos pasos no vengan. Si ninguno de los ids
// aparece en lo que trajo el calendario, queda anotado para auditarlo.
const idsCreados = new Set((Array.isArray(item.eventosCreados) ? item.eventosCreados : [])
  .map((e) => String((e && e.id) || '')).filter(Boolean));
const citaCreadaNoEncontrada = idsCreados.size > 0
  && ![...idsCreados].some((id) => todos.some((e) => String(e.id) === id));

const recien = todos.filter(e => {
  if (idsCreados.has(String(e.id))) return true;
  const c = Date.parse(e.created || e.updated || '');
  return Number.isFinite(c) && (ahora - c) >= 0 && (ahora - c) < VENTANA_MS;
});

// Instante de inicio y fin de un evento. Los de dia completo (`start.date`) se
// dejan afuera a proposito: suelen ser notas del negocio -- "feriado", "cerrado
// por inventario" -- y tomarlos como ocupacion bloquearia el dia entero.
const rango = (e) => {
  const i = Date.parse(e?.start?.dateTime || '');
  const f = Date.parse(e?.end?.dateTime || '');
  return Number.isFinite(i) && Number.isFinite(f) ? { i, f } : null;
};
// Media abierta: una cita de 9 a 10 y otra de 10 a 11 NO se superponen.
const seSuperponen = (a, b) => a.i < b.f && b.i < a.f;
const creado = (e) => Date.parse(e.created || e.updated || '') || 0;

// --- CANDADO ---------------------------------------------------------------
// Quien se queda con el horario: la cita creada ANTES.
//
// EL DESEMPATE NO ES UN DETALLE, es lo que hacia que el candado no sirviera.
// La primera version exigia que la otra cita fuera ESTRICTAMENTE anterior. El
// 2026-09-06, en la ejecucion #1076, el agente agendo tres citas en un mismo
// mensaje y las dos que chocaban quedaron con el MISMO `created`
// -- 00:20:52 las dos, porque Google guarda ese campo con resolucion de
// segundos --. Ninguna era anterior a la otra, ninguna cedio, y las dos
// sobrevivieron: un funcionario con dos citas de 9 a 10, que es justo lo que
// esto tenia que impedir.
//
// Ahora, con marcas iguales, desempata el identificador. Cualquier criterio
// sirve mientras sea DETERMINISTA: lo que no puede pasar es que las dos se
// crean con derecho al horario, ni que las dos cedan y el negocio se quede sin
// ninguna.
const ganaPrioridad = (a, b) => {
  const ca = creado(a);
  const cb = creado(b);
  if (ca !== cb) return ca < cb;
  return String(a.id) < String(b.id);
};

const ceden = [];
for (const nueva of recien) {
  const r = rango(nueva);
  const calendario = nueva.organizer && nueva.organizer.email;
  if (!r || !calendario) continue;

  const choque = todos.find((otro) => {
    if (otro.id === nueva.id) return false;
    if (!otro.organizer || otro.organizer.email !== calendario) return false;
    const ro = rango(otro);
    return ro && seSuperponen(r, ro) && ganaPrioridad(otro, nueva);
  });

  if (choque) ceden.push(nueva);
}

if (ceden.length) {
  // Las que NO ceden siguen siendo citas validas. Importa para el cobro: si el
  // cliente pidio tres y solo una choco, hubo cierre igual.
  const sobreviven = recien.filter((e) => !ceden.some((c) => c.id === e.id));

  // Nombre y hora de cada cita caida, para poder decirle al cliente CUAL fue.
  // Un "hubo un cruce" a secas, cuando se agendaron tres, no le dice a quien
  // tiene que volver a llamar.
  const describir = (e) => {
    const quien = String(e.summary || '').replace(/^Cita\s+/i, '').split('—')[0].trim();
    let hora = '';
    try {
      hora = new Date(e.start.dateTime).toLocaleTimeString('es-BO', {
        hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'America/La_Paz',
      });
    } catch (err) { hora = ''; }
    return quien && hora ? `${quien} a las ${hora}` : (quien || hora || 'una de las citas');
  };
  const caidas = ceden.map(describir).join(' y ');

  const configurado = String(cfgCampo('mensajeReservaNoConfirmada') || '').trim();
  const aviso = configurado
    || `Disculpa, tengo que corregirte algo: la cita de ${caidas} no quedo, `
     + 'porque ese horario ya estaba ocupado con la misma persona. El resto de lo '
     + 'que agendamos si esta bien. Le paso este pedido a recepcion para darte '
     + 'otro horario enseguida.';

  // QUIEN Y CUANDO, para el reintento (2026-09-17). Cuando la cita nueva cede,
  // el flujo ya no manda el texto fijo de una: le da al modelo UN turno mas
  // (`Reintento tras cruce`) para ofrecer alternativas, y ese turno necesita
  // saber que horario y que persona chocaron. La persona sale del calendario
  // donde vivia la cita, cruzado con `funcionarios` de la configuracion: es el
  // dato firme; el titulo de la cita solo trae el nombre del cliente.
  let equipo = [];
  try { equipo = JSON.parse(cfgCampo('funcionarios') || '[]'); } catch (err) { equipo = []; }
  const personaDe = (calendario) => {
    const f = Array.isArray(equipo) ? equipo.find((x) => x && x.calendario === calendario) : null;
    return f && f.nombre ? String(f.nombre) : '';
  };
  const citasCaidas = ceden.map((e) => {
    let hora = '';
    let fecha = '';
    try {
      const d = new Date(e.start.dateTime);
      hora = d.toLocaleTimeString('es-BO', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'America/La_Paz' });
      fecha = d.toLocaleDateString('es-BO', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/La_Paz' });
    } catch (err) { hora = ''; fecha = ''; }
    const servicio = String(e.summary || '').split('—')[1];
    return { hora, fecha, persona: personaDe(e.organizer.email), servicio: servicio ? servicio.trim() : '', inicio: e.start.dateTime || '' };
  });

  // LA TRANSFERENCIA YA NO SE DECIDE ACA. Antes el primer item salia con
  // `transferir: true` y la rama directa a `¿Transferir a humano?` avisaba a
  // recepcion siempre. Ahora el motivo viaja en `motivoCruce` y deciden
  // `Retomar respuesta` y `Procesar reintento`: si el modelo logro ofrecer
  // alternativas, el cliente no esta esperando a nadie y el aviso seria un
  // mensaje pagado que dice algo falso («necesita atencion humana»); si el
  // reintento no sale, ahi si va el aviso, con este mismo motivo.
  //
  // Un item por cita a deshacer: el nodo de Calendar borra uno por item.
  const motivoCruce = 'se intento agendar sobre un horario YA OCUPADO de la misma persona '
    + `(${ceden.map((c) => c.summary || 'sin titulo').join('; ')}); la cita nueva se deshizo`;
  return ceden.map((e) => ({ json: { ...item,
    respuesta: aviso,
    reservaVerificada: sobreviven.length > 0,
    eventoId: sobreviven.length > 0 ? sobreviven[0].id : undefined,
    citaSolapada: true,
    eventoABorrar: e.id,
    calendarioDelBorrado: e.organizer.email,
    citasCaidas,
    transferir: false,
    motivoTransferencia: '',
    motivoCruce,
  }, pairedItem: { item: 0 } }));
}

function cfgCampo(nombre) {
  try { return $('Config del negocio').first().json[nombre]; }
  catch (e) { return ''; }
}

// Duplicado por titulo: la cita existe, al cliente se le confirma igual --
// negarlo seria mentirle -- pero recepcion tiene que borrar la sobrante.
const porTitulo = {};
for (const e of recien) porTitulo[e.summary || ''] = (porTitulo[e.summary || ''] || 0) + 1;
const repetidos = Object.entries(porTitulo).filter(([, n]) => n > 1);

if (repetidos.length) {
  // El evento queda igual (bloque 2): con seña activa el QR se manda para la
  // cita que sobrevive; recepcion borra las repetidas con el aviso de abajo.
  return [{ json: { ...item, reservaVerificada: true, eventoId: recien[0].id, duplicados: repetidos.length,
    transferir: true,
    motivoTransferencia: `se crearon citas DUPLICADAS (${repetidos.map(([t, n]) => `${n}x ${t}`).join('; ')}), hay que borrar las sobrantes` }, pairedItem: { item: 0 } }];
}

// AVISO POR "NO VERIFICADA": DESACTIVADO. La consulta de verificacion fallaba
// siempre cuando se escribio esto; hoy si encuentra las citas (comprobado en la
// ejecucion #964), pero el aviso se deja apagado hasta tener mas evidencia de
// que no genera ruido. El registro queda en el item para poder auditarlo.
if (recien.length === 0) {
  return [{ json: { ...item, reservaVerificada: false, verificacionSinDatos: true, citaCreadaNoEncontrada }, pairedItem: { item: 0 } }];
}

return [{ json: { ...item, reservaVerificada: true, eventoId: recien[0].id, citaCreadaNoEncontrada }, pairedItem: { item: 0 } }];

// El comercio no esta operativo (suspendido o dado de baja).
// PROHIBIDO revelar el motivo: el cliente final no tiene por que enterarse de
// que el negocio debe dinero. El texto es neutro y sale de Config del negocio.
// Se corta ANTES del agente, asi que un comercio suspendido no consume ni
// tokens ni llamadas al calendario.
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeComercioSuspendido ?? '').trim()
  || 'En este momento no podemos atenderte por este medio. Gracias por escribirnos.';

return $input.all().map(i => ({ json: {
  respuesta: aviso,
  transferir: false,
  comercioSuspendido: true,
  estadoComercio: cfg.estadoComercio,
  from: i.json.from,
  nombrePerfil: i.json.nombrePerfil,
}}));

// Emite un item por CADA calendario configurado.
//
// Hace falta porque `agendar_cita` escribe en el calendario del servicio -- el
// de belleza o el de odontologia -- mientras que la verificacion leia el
// calendario por defecto. Nunca encontraba nada, la compuerta mandaba la
// disculpa, el cliente insistia y el agente volvia a agendar: el 2026-08-30 eso
// produjo TRES pedicures y TRES ortodoncias identicas.
//
// El nodo de Calendar corre una vez por item, asi que emitiendo uno por
// calendario se revisan todos y `Comprobar reserva` junta los resultados.
const cfg = $('Config del negocio').first().json;

// LAS AGENDAS DE LOS FUNCIONARIOS TAMBIEN. Si una persona tiene calendario
// propio y la verificacion no lo mira, vuelve a pasar lo del 2026-08-30: la
// compuerta no encuentra la cita, manda la disculpa, el cliente insiste y se
// agenda de nuevo. Tres citas para la misma persona.
let equipoCal = [];
try {
  equipoCal = JSON.parse(cfg.funcionarios || '[]')
    .map((f) => f && f.calendario).filter(Boolean);
} catch (e) { equipoCal = []; }

let mapa = {};
try { mapa = JSON.parse(cfg.calendariosPorServicio || '{}'); } catch (e) { mapa = {}; }

const calendarios = [...new Set([cfg.calendarioId, ...Object.values(mapa), ...equipoCal].filter(Boolean))];

const base = $input.first().json;
return calendarios.map(calendarioARevisar => ({ json: { ...base, calendarioARevisar } }));

// El nodo de Calendar devuelve el resultado del borrado, no la conversacion.
// Se retoma el item de `Comprobar reserva` para que lo que sigue encuentre
// `respuesta`, `from` y el resto donde los espera.
//
// Y DECIDE SI HAY REINTENTO (2026-09-17, ejecucion #2867 de Clinica Platinum).
// El candado deshizo una cita solapada y el paciente recibio un texto fijo y
// una transferencia, sin ninguna alternativa; la clinica lo reclamo. Desde
// aca, si el borrado salio bien, el flujo le da al modelo UN turno mas
// (`Reintento tras cruce`) para decir que el horario estaba ocupado y ofrecer
// hasta tres alternativas verificadas. Si el borrado FALLO, no: la cita
// fantasma sigue en la agenda y decirle al cliente que «no quedo» seria
// mentirle; ahi va el texto fijo, la transferencia y el aviso, como siempre.
const base = $('Comprobar reserva').first().json;
const borradoFallo = $input.all().some((i) => i.json && i.json.error !== undefined);
const caidas = Array.isArray(base.citasCaidas) ? base.citasCaidas : [];

// Frase para el aviso del sistema al modelo: «las 14:30 del miercoles 17 de
// septiembre con el Dr. X». Sin hora conocida se describe lo que haya.
const describir = (c) => {
  const cuando = [c.hora ? `las ${c.hora}` : '', c.fecha ? `del ${c.fecha}` : ''].filter(Boolean).join(' ');
  const quien = c.persona ? ` con ${c.persona}` : '';
  return (cuando || 'el horario pedido') + quien;
};
const notaCruce = caidas.length
  ? `el horario de ${caidas.map(describir).join(' y el de ')} ya estaba ocupado`
  : 'el horario pedido ya estaba ocupado con esa persona';

// El texto original del cliente vuelve a entrar en el turno del reintento:
// `Olvidar turno fallido` borra de la memoria el turno que no se envio, y sin
// esto la conversacion guardada perderia lo que el cliente pidio.
let userInput = '';
try { userInput = String($('Normalizar entrada').first().json.userInput || ''); } catch (e) { userInput = ''; }

const reintentar = !borradoFallo && caidas.length > 0;
const motivo = base.motivoCruce || 'hubo un cruce de horario';
return [{ json: { ...base,
  reintentar,
  notaCruce,
  userInput,
  // Sin reintento, la red de seguridad de siempre: texto fijo y recepcion.
  transferir: !reintentar,
  motivoTransferencia: reintentar ? '' : (borradoFallo
    ? `${motivo}, PERO NO SE PUDO DESHACER la cita nueva: hay dos citas a la misma hora en esa agenda y el cliente recibio el aviso de que no se pudo confirmar`
    : `${motivo} y el cliente quedo esperando otro horario`),
}, pairedItem: { item: 0 } }];

// LA CONSOLA MANDA, PERO NUNCA DEJA AL CLIENTE SIN RESPUESTA.
//
// QUE RESUELVE. Hasta hoy el negocio escribia su configuracion en la consola y
// el asistente seguia usando la que tenia adentro: cambiar un precio o un
// horario no hacia absolutamente nada. Era EL defecto que un cliente iba a
// descubrir solo, probando, y el que dejaba sin sustento la promesa de
// «configuralo vos».
//
// COMO. `Traer configuracion` pide al panel la ficha del negocio. Si contesta,
// sus valores PISAN a los de `Config base`. Si no contesta, o contesta algo
// raro, se usan los de siempre: el peor caso es el comportamiento de ayer.
//
// POR QUE ESTE NODO SE LLAMA «Config del negocio». Porque asi se llamaba el Set
// que traia los valores escritos a mano, y hay veinte expresiones en el flujo
// -- herramientas, prompt, nodos de salida -- que lo buscan por ese nombre.
// Heredando el nombre, todas recogen la version fusionada sin tocar ninguna.
// El Set paso a llamarse «Config base».
//
// SOLO SE PISA LO QUE VIENE CON CONTENIDO. Un campo vacio en la consola no
// borra el valor de respaldo: el negocio que todavia no cargo su direccion
// tiene que comportarse como antes, no peor.
const base = $('Config base').first().json;

// ---------------------------------------------------------------------------
// EL 409 NO ES UN FALLO: ES LA RESPUESTA QUE CORTA EL SERVICIO.
//
// EL DEFECTO QUE ESTO ARREGLA (reportado el 2026-09-07, y confirmado en los
// TRES flujos). `configuracionFlujo` contesta 409 con `{estado, mensajeCortesia}`
// y SIN `tenantId` cuando el comercio no esta activo. La version anterior de
// este nodo exigia `tenantId` para dar la respuesta por buena, asi que un 409
// caia al respaldo... y el respaldo dice `estadoComercio: 'operativo'` escrito a
// mano. Resultado: **un comercio suspendido seguia siendo atendido**, y en el
// flujo de recordatorios seguia enviando plantillas que Meta cobra. Era
// exactamente el defecto que conectar el panel daba por cerrado, y yo lo habia
// afirmado por escrito sin comprobarlo.
//
// LA RAIZ ERA NO PODER DISTINGUIR «el panel dice que esta suspendido» de «el
// panel no contesto». Los dos se veian igual: un fallo. Ahora el nodo HTTP
// devuelve la respuesta completa -codigo y cuerpo- y aca se decide con el
// codigo:
//
//   200 + tenantId  -> configuracion del panel
//   409             -> SUSPENDIDO. Es una respuesta valida, no un error.
//   cualquier otra  -> no se pudo saber -> respaldo
//
// SOBRE `neverError`, QUE ESTE PROYECTO PROHIBIO EL 2026-09-01: aquel caso era
// un nodo que salia VERDE con un 401 y nadie miraba el resultado. Aca el codigo
// se examina explicitamente y lo que no se reconoce cae al respaldo dejando
// rastro. La regla real no es «nunca neverError», es «nunca ignores el codigo».

const respuesta = $input.first().json ?? {};
const codigo = Number(respuesta.statusCode);
const cuerpo = (respuesta.body ?? {});

const util = (v) => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const soloLlenos = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));

// EL NOMBRE DEL ASISTENTE lo elige cada empresa en la consola y vale para todos
// sus flujos (decidido el 15/09/2026). Es TEXTO LIBRE y va al prompt: se deja en
// una sola linea, sin corchetes ni llaves -- con ellos podria imitar un bloque
// [CONTEXTO DEL SISTEMA] -- ni comillas angulares, que el prompt usa para
// citarlo, y con el tope de 40 del servidor. Vacio = el asistente de siempre.
// La regla de identidad (asistente virtual con IA, no lo niega) NO depende de
// este campo: esta escrita en el prompt y en los textos fijos, con o sin nombre.
const nombreDelAsistente = (v) => {
  if (typeof v !== 'string') return undefined;
  const t = util(v.replace(/[\u0000-\u001f\u007f\u2028\u2029\[\]{}<>«»]/g, ' ').replace(/\s+/g, ' '));
  return t ? t.slice(0, 40).trim() : undefined;
};
// Cuantos emojis llevan los TEXTOS FIJOS, los que no pasan por el modelo. Al
// modelo se lo dice `estiloEmojis`; esto es para lo que el flujo escribe solo.
const NIVELES_EMOJIS = ['ninguno', 'pocos', 'muchos'];

// ---------------------------------------------------------------------------
// ESTADO DE ATENCION DEL TELEFONO: los umbrales de uso extendido
// (`Analisis/27` §5, decididos el 13/09/2026).
//
// `Traer configuracion` manda el telefono que escribio, y el panel contesta en
// `atencion` cuantas respuestas lleva ese cliente en su ventana de 24 h y que
// hacer con ESTE turno:
//   normal    -> al modelo, como siempre.
//   operador  -> paso el umbral de operador (50 por defecto): NO se llama al
//                modelo; se responde un aviso fijo y, la primera vez, se avisa
//                al negocio para que una persona tome la conversacion.
//   bloqueado -> paso el umbral de bloqueo (100 por defecto): no se envia nada
//                hasta que la ventana se renueve.
// Los umbrales los fija NovuChat por empresa en el panel. El flujo no cuenta
// nada: obedece. Quien decide es el servidor (`atencion.ts`).
//
// ANTE LA DUDA, NORMAL. Si el panel no contesta, contesta 409 o manda un
// estado que no se reconoce, el estado es `normal`: el mismo criterio de
// arriba, una caida del panel no puede dejar sin respuesta a un cliente. El
// techo de costo lo vuelve a poner el servidor en el primer turno que conteste.
// ---------------------------------------------------------------------------
const at = (codigo === 200 && cuerpo && typeof cuerpo.atencion === 'object' && cuerpo.atencion)
  ? cuerpo.atencion : {};
const atencion = {
  atencionEstado: ['normal', 'operador', 'bloqueado'].includes(at.estado) ? at.estado : 'normal',
  // El texto lo pone el panel; este es el respaldo, identico al del servidor
  // (`MENSAJE_USO_EXTENDIDO` en atencion.ts). Neutro: no habla de limites, de
  // mensajes ni de dinero, porque quien lo lee es un tercero.
  atencionMensajeFijo: util(at.mensajeFijo)
    || 'Gracias por su paciencia. Para atenderle mejor, una persona del equipo va a continuar esta conversación en breve.',
  atencionAvisarRecepcion: ['operador', 'bloqueado'].includes(at.avisarRecepcion) ? at.avisarRecepcion : '',
  atencionRespuestas: (typeof at.respuestasEnVentana === 'number' && Number.isFinite(at.respuestasEnVentana))
    ? at.respuestasEnVentana : 0,
  atencionVenceEn: util(at.ventanaVenceEn) || '',
};

if (codigo === 409) {
  return [{ json: { ...base, ...atencion,
    estadoComercio: 'suspendido',
    // El texto neutro lo pone el panel: no menciona pagos ni deudas, porque el
    // cliente final no tiene por que enterarse de que el negocio debe dinero.
    mensajeComercioSuspendido: util(cuerpo.mensajeCortesia)
      || base.mensajeComercioSuspendido,
    configDeLaConsola: false,
    panelDice: 'no operativo',
  } }];
}

const contesto = codigo === 200 && cuerpo && typeof cuerpo.tenantId === 'string';
if (!contesto) {
// Sin respuesta no se corta: una caida del panel no puede dejar sin asistente a
// todos los comercios. Un cliente escribiendo merece una respuesta.
  return [{ json: { ...base, ...atencion,
    estadoComercio: base.estadoComercio ?? 'operativo',
    configDeLaConsola: false,
    panelSinRespuesta: true,
    codigoDelPanel: Number.isFinite(codigo) ? codigo : 0,
  } }];
}

const r = cuerpo;

const dn = r.datosDelNegocio ?? {};
const op = r.operacion ?? {};

// --- CATALOGO -------------------------------------------------------------
// Se parte por PRECIO, no por rubro, porque es lo que cambia como habla el
// asistente: lo que tiene precio se cotiza en el chat; lo que no, se cotiza
// despues de evaluar. Un servicio sin precio no es un dato faltante.
const items = Array.isArray(r.catalogo) ? r.catalogo : [];
const conPrecio = items.filter((i) => typeof i.precio === 'number');
const sinPrecio = items.filter((i) => typeof i.precio !== 'number');
// «BOB» es el codigo ISO y no se le dice a un cliente: en Bolivia se dice
// «Bs». El asistente lee esta lista en voz alta.
const simbolo = (m) => (m === 'USD' ? 'USD' : 'Bs');
const monedaNegocio = simbolo(util(op.moneda));
const listaConPrecio = conPrecio
  .map((i) => `${i.nombre} ${i.precio} ${i.moneda ? simbolo(i.moneda) : monedaNegocio}`).join(' · ');
const listaSinPrecio = sinPrecio.map((i) => i.nombre).join(', ');

// --- FUNCIONARIOS ---------------------------------------------------------
// El panel los devuelve como objetos; el flujo los lee como texto JSON con las
// claves que ya usan las herramientas de calendario.
const equipo = Array.isArray(r.funcionarios) ? r.funcionarios.map((f) => ({
  nombre: f.nombre,
  servicios: Array.isArray(f.servicios) ? f.servicios : [],
  calendario: f.calendario || f.calendarioId || '',
})).filter((f) => f.nombre) : [];

// --- DONDE QUEDA EL LOCAL (Analisis/34 §2) ----------------------------------
// El enlace de Google Maps va en el MISMO mensaje que la direccion -- en la
// confirmacion de la cita y ante «donde quedan?» --: cero mensajes nuevos. El
// servidor ya lo filtro por dominio (`enlaceDeMapaValido`, prompt.ts); aca se
// vuelve a mirar porque es lo unico que el asistente reenvia TAL CUAL a un
// cliente, y un enlace ajeno con el nombre del negocio no puede salir por una
// caida de la validacion de arriba. Las coordenadas del pin llegan en
// `operacion.ubicacion` como numeros y se guardan como texto, porque Config
// base es un Set de textos; `Procesar respuesta` las vuelve numero. Sin
// coordenadas no hay pin: el texto ya lleva la direccion y el enlace.
const ENLACE_MAPA = /^https:\/\/(maps\.app\.goo\.gl|goo\.gl\/maps|www\.google\.com\/maps|google\.com\/maps|maps\.google\.com)([/?][A-Za-z0-9._~:/?#@!$&()*+,;=%-]*)?$/;
const enlaceDeMapa = (v) => { const t = util(v); return t && t.length <= 200 && ENLACE_MAPA.test(t) ? t : undefined; };
const coordenada = (u, clave, max) => (u && typeof u === 'object' && typeof u[clave] === 'number'
  && Number.isFinite(u[clave]) && Math.abs(u[clave]) <= max) ? String(u[clave]) : undefined;

const deLaConsola = soloLlenos({
  nombreNegocio: util(dn.nombreNegocio),
  descripcion: util(dn.descripcion),
  direccion: util(dn.direccion),
  direccionMaps: enlaceDeMapa(dn.direccionMaps),
  ubicacionLat: coordenada(op.ubicacion, 'lat', 90),
  ubicacionLng: coordenada(op.ubicacion, 'lng', 180),
  politicaCancelacion: util(dn.politicaCancelacion),
  mensajeCierre: util(dn.mensajeCierre),
  mensajeErrorTemporal: util(dn.mensajeErrorTemporal),
  mensajeReservaNoConfirmada: util(dn.mensajeReservaNoConfirmada),
  mensajeComercioSuspendido: util(dn.mensajeComercioSuspendido),
  numeroRecepcion: util(op.numeroRecepcion),
  calendarioId: util(op.calendarioId),
  horarioAtencion: util(op.horarioAtencion),
  // `datosQueNoTenemos` lo calcula el panel mirando que campos quedaron vacios.
  datosQueNoTenemos: Array.isArray(dn.datosQueNoTenemos) && dn.datosQueNoTenemos.length
    ? dn.datosQueNoTenemos.join(', ') : undefined,
  funcionarios: equipo.length ? JSON.stringify(equipo) : undefined,
  catalogoConPrecio: listaConPrecio || undefined,
  catalogoSinPrecio: listaSinPrecio || undefined,
  // La voz sale de opciones cerradas del panel, nunca de texto libre.
  // La voz sale ROTULADA del panel (`voz`), no del arreglo
  // `instruccionesDeVoz`: leerlo por posicion se rompe el dia que
  // aparezca una tercera frase.
  tratamiento: util((r.voz ?? {}).tratamiento),
  estiloEmojis: util((r.voz ?? {}).emojis),
  nombreAsistente: nombreDelAsistente((r.voz ?? {}).nombreAsistente),
  nivelEmojis: NIVELES_EMOJIS.includes((r.voz ?? {}).nivelEmojis) ? r.voz.nivelEmojis : undefined,
});

// --- SEÑA PARA RESERVAR (bloque 2, Analisis/30 §4) -------------------------
// El panel manda `sena` solo al flujo de agendamiento: `activa` exige un
// importe mayor que cero Y el QR del comercio registrado y encendido (el
// servidor lo decide; aca se vuelve a exigir la URL del QR porque es lo que
// se manda TAL CUAL en el mensaje de imagen). Todo viaja como texto, porque
// Config base es un Set de textos. `pendiente`, `evento` son de ESTE telefono:
// si hay un QR pendiente, la proxima foto o PDF es el comprobante
// (`Normalizar entrada`). Sin `sena` en la respuesta, o con el panel caido,
// queda el respaldo de Config base: seña inactiva, y el flujo agenda como
// siempre, sin mandar ningun mensaje de mas.
const sn = (r.sena && typeof r.sena === 'object') ? r.sena : {};
const qrSena = (sn.qr && typeof sn.qr === 'object') ? sn.qr : {};
const senaActiva = sn.activa === true && typeof sn.importe === 'number' && Number.isFinite(sn.importe)
  && sn.importe > 0 && typeof qrSena.url === 'string' && /^https:\/\//.test(qrSena.url);
const evSena = (sn.evento && typeof sn.evento === 'object') ? sn.evento : {};
const minutosSena = (typeof sn.minutosRetencion === 'number' && Number.isInteger(sn.minutosRetencion)
  && sn.minutosRetencion >= 5 && sn.minutosRetencion <= 180) ? String(sn.minutosRetencion) : undefined;
const laSena = {
  senaActiva: senaActiva ? 'si' : '',
  senaImporte: senaActiva ? String(sn.importe) : '',
  senaMoneda: simbolo(util(sn.moneda) || util(op.moneda)),
  senaMinutosRetencion: minutosSena || String(base.senaMinutosRetencion || '30'),
  senaQrUrl: senaActiva ? qrSena.url.trim() : '',
  senaNombreCuenta: senaActiva ? String(qrSena.nombreCuenta || '').trim().slice(0, 120) : '',
  senaBanco: senaActiva ? String(qrSena.banco || '').trim().slice(0, 80) : '',
  senaPendiente: sn.pendiente === true ? 'si' : '',
  senaEventoId: typeof evSena.id === 'string' ? evSena.id.slice(0, 200) : '',
  senaEventoCalendario: typeof evSena.calendario === 'string' ? evSena.calendario.slice(0, 200) : '',
};

// `estadoComercio` NO se toma del respaldo: si el panel dice que el comercio no
// esta operativo, manda el panel. Es lo que corta el servicio a quien dejo de
// pagar, y no puede depender de un valor escrito adentro del flujo.
const estadoComercio = util(r.estadoComercio) === 'activo' ? 'operativo'
  : (util(r.estadoComercio) ? 'suspendido' : base.estadoComercio);

return [{ json: { ...base, ...atencion, ...deLaConsola, ...laSena, estadoComercio, configDeLaConsola: true } }];

// USO EXTENDIDO: el cliente paso el umbral de operador o el de bloqueo
// (`Analisis/27` §5). El estado lo decide el panel; ver `Config del negocio`.
//
// NO SE LLAMA AL MODELO en ninguno de los dos casos: este nodo cuelga de la
// rama falsa de `¿Atención normal?`, antes del agente. Es lo que pone techo al
// costo de una ventana: pasado el umbral de operador cada consulta cuesta un
// mensaje fijo, y pasado el de bloqueo no cuesta nada.
//
//   operador  -> se responde el aviso fijo, y se reporta como saliente: cuenta
//                y se factura como cualquier respuesta. La PRIMERA vez que se
//                entra en este estado se avisa a recepcion.
//   bloqueado -> no se responde nada. La primera vez se avisa a recepcion.
//
// `transferir` y `motivoTransferencia` son los campos que ya leen
// `¿Transferir a humano?` y `Avisar a recepción`: se reutilizan esos nodos en
// vez de crear otro envio, porque un nodo de WhatsApp nuevo no recibiria la
// credencial al publicar (publicar-flujo.sh la injerta por NOMBRE de nodo).
//
// «EN SU VENTANA DE 24 HORAS» y no «hoy»: la ventana arranca con el primer
// mensaje del cliente y no coincide con el dia calendario.
const FIJO = 'Gracias por su paciencia. Para atenderle mejor, una persona del equipo va a continuar esta conversación en breve.';

// «hasta mañana» si no se sabe cuando vence; «hasta el <dia y hora>» si se sabe.
const hasta = (iso) => {
  if (!iso) return 'mañana';
  try {
    return 'el ' + new Date(iso).toLocaleString('es-BO', {
      timeZone: 'America/La_Paz', weekday: 'long', hour: '2-digit', minute: '2-digit',
    });
  } catch (e) {
    return 'el ' + iso;
  }
};

return $input.all().map((i) => {
  const j = i.json;
  const estado = j.atencionEstado === 'bloqueado' ? 'bloqueado' : 'operador';
  const aviso = j.atencionAvisarRecepcion === 'operador' || j.atencionAvisarRecepcion === 'bloqueado';
  const n = Number(j.atencionRespuestas) || 0;
  return { json: {
    from: j.from,
    nombrePerfil: j.nombrePerfil,
    atencionEstado: estado,
    responder: estado === 'operador',
    respuesta: estado === 'operador' ? (String(j.atencionMensajeFijo ?? '').trim() || FIJO) : '',
    transferir: aviso,
    motivoTransferencia: estado === 'operador'
      ? `uso extendido: ${n} respuestas del asistente en su ventana de 24 horas. El asistente dejó de responder con IA y le avisó que lo atiende una persona`
      : `llegó a ${n} respuestas del asistente en su ventana de 24 horas. El asistente no le responde más hasta ${hasta(j.atencionVenceEn)}; si hace falta, escríbale directamente`,
  } };
});

// PUNTO UNICO DE SALIDA AL CLIENTE (2026-09-17, ejecucion #2867 de Platinum).
//
// EL DEFECTO. `Reportar mensaje (saliente)` colgaba de `Procesar respuesta`,
// ANTES del candado, y reportaba lo que el modelo habia escrito. Cuando el
// candado deshizo una cita solapada y cambio el texto, la consola mostro
// «¡Listo! Quedó agendada…» mientras el telefono recibio «Disculpe, no pude
// confirmar…». La consola es lo que el comercio usa para saber que paso, y
// mentia.
//
// EL ARREGLO. Todo camino que termina en `Responder al cliente` pasa por aca
// -- respuesta normal, reintento tras un cruce, texto fijo, comercio no
// operativo, uso extendido -- y el reporte cuelga DESPUES del envio y lee de
// este nodo: reporta exactamente lo que salio, y solo si salio (un envio
// rechazado por Meta corta la ejecucion antes de llegar al reporte).
//
// Es un nodo de paso: no decide nada. Solo deja el item con `pairedItem`
// explicito para que `$('Mensaje a enviar').item` resuelva aunque el camino
// venga de nodos que construyen items nuevos.
//
// Lo UNICO que toca del texto es la negrita de Markdown (2026-09-17): como
// todo lo que sale al cliente pasa por aca -- tambien los textos fijos que el
// comercio escribe en su consola --, un **asi** que llegara desde cualquier
// rama sale como *asi*. La misma linea que en `Procesar respuesta` y
// `Procesar reintento`; una prueba exige que las tres sean identicas.
const NEGRITA_MD = (t) => String(t).replace(/\*\*\*([^*\n]+?)\*\*\*/g, '*_$1_*').replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
return $input.all().map((i, idx) => ({
  json: { ...i.json, respuesta: NEGRITA_MD(i.json.respuesta ?? '') },
  pairedItem: { item: idx },
}));

// EL SEGUNDO TURNO TRAS UN CRUCE DE HORARIO (2026-09-17).
//
// `Reintento tras cruce` NO tiene la herramienta de agendar: por diseño no
// puede crear una cita, asi que aca no hay nada que verificar en el
// calendario. Lo que si hay que vigilar es lo que DICE: si afirma que agendo,
// le mentiria al cliente igual que la respuesta que se deshizo. En ese caso,
// si el modelo fallo o si devolvio vacio, se cae a la red de seguridad de
// siempre: el texto fijo de `Config del negocio`, la transferencia y el aviso
// a recepcion. Una sola vez: este nodo no vuelve al agente.
const base = $('Retomar respuesta').first().json;
const dato = ($input.first() && $input.first().json) || {};
const fallo = dato.error !== undefined || dato.output === undefined;
const bruto = String(dato.output ?? '');
const marca = bruto.includes('[TRANSFERIR]');
// Negrita de WhatsApp por construccion: la misma linea que en `Procesar
// respuesta` y `Mensaje a enviar` (ver el comentario alla).
const NEGRITA_MD = (t) => String(t).replace(/\*\*\*([^*\n]+?)\*\*\*/g, '*_$1_*').replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
const texto = NEGRITA_MD(bruto.split('[TRANSFERIR]').join('').trim());
// Los detectores juzgan el texto sin marcas de formato.
const plano = texto.replace(/[*_~]/g, '');

// LOS MISMOS DETECTORES QUE `Procesar respuesta`, letra por letra: una prueba
// (`platinum-flujo.test.ts`) exige que sean identicos para que un ajuste en
// uno no deje al otro con una version vieja.
const CONFIRMA = /(ha sido|han sido|queda|quedó|quedo|fue|está|esta|ya está|ya esta)\s+(agendad|reservad|registrad|confirmad|reprogramad|reagendad|movid|cambiad|anotad)|\b(he|hemos)\s+(agendado|reservado|registrado|confirmado|reprogramado|reagendado|movido|anotado)\b|(agendé|reservé|registré|reprogramé|reagendé|moví)(?![a-záéíóúñ])|\b(te|le|les|los|las)\s+anot(é|amos)(?![a-záéíóúñ])|\b(cambié|cambiamos|moví|movimos)\s+(tu|su|la)\s+cita\b|\b(cita|reserva|turno)\b[^.!?]{0,40}?\b(agendad|reservad|registrad|confirmad|reprogramad|reagendad|movid|cambiad)[oa]s?\b/i;
const NIEGA = /\bno\s+(pude|se pudo|pudimos|quedó|quedo|está|esta)\b/i;
const YA_EXISTE = /\bya\s+(tiene|tienes|cuenta con|hay)/i;
// Y uno propio de este turno: «ese horario ya esta ocupado» es exactamente lo
// que el reintento tiene que decir, y CONFIRMA lo confunde con «esta
// reservado» de una cita nueva.
const OCUPADO = /\b(ya\s+)?(est[aá]|estaba|se encuentra|estar[ií]a)\s+(ocupad|reservad|tomad)|\bya\s+no\s+est[aá]\s+disponible/i;
// Se juzga ORACION por ORACION: un «no quedo registrada» al principio no
// puede tapar un «quedo agendada a las 15:00» al final.
const oraciones = plano.split(/[.!?\n]+/).map((s) => s.trim()).filter(Boolean);
const afirmaAgendo = oraciones.some((s) =>
  CONFIRMA.test(s) && !NIEGA.test(s) && !YA_EXISTE.test(s) && !OCUPADO.test(s));

const motivo = base.motivoCruce || 'hubo un cruce de horario';
const salio = !fallo && texto !== '' && !afirmaAgendo;
if (salio) {
  return [{ json: { ...base,
    respuesta: texto,
    transferir: marca,
    motivoTransferencia: marca
      ? `${motivo}; al ofrecer alternativas el asistente pidio atencion humana`
      : '',
    reintentoTrasCruce: 'ok',
  }, pairedItem: { item: 0 } }];
}

const porQue = fallo ? 'fallo el modelo' : (texto === '' ? 'el modelo no devolvio texto' : 'el modelo volvio a afirmar que agendo');
return [{ json: { ...base,
  respuesta: base.respuesta,
  transferir: true,
  motivoTransferencia: `${motivo}; el reintento de ofrecer alternativas no salio (${porQue}) y el cliente quedo esperando otro horario`,
  reintentoTrasCruce: fallo ? 'fallo' : (texto === '' ? 'vacio' : 'afirmo-agendar'),
}, pairedItem: { item: 0 } }];

